import json, time

def safe_json_call(client, system_prompt, user_text, retries=3):
 for attempt in range(retries):
 try:
 r = client.chat.completions.create(
 model='gpt-4o-mini',
 messages=[
 {'role':'system','content': system_prompt},
 {'role':'user','content': user_text}
 ]
 )
 content = r.choices[0].message.content.strip()
 return json.loads(content) # will raise if not valid JSON
 except json.JSONDecodeError:
 print(f'Attempt {attempt+1}: invalid JSON, retrying...')
 time.sleep(1)
 raise ValueError('AI did not return valid JSON after 3 attempts')

