import time

def with_retry(fn, max_retries=3, delay=2):
 '''Retry a function up to max_retries times with delay between attempts.'''
 for attempt in range(max_retries):
 try:
 return fn()
 except Exception as e:
 if attempt == max_retries - 1:
 raise
 print(f'Attempt {attempt+1} failed: {e}. Retrying in {delay}s...')
 time.sleep(delay)

def with_fallback(fn, fallback_fn):
 '''Try fn. If it fails, run fallback_fn instead.'''
 try:
 return fn()
 except Exception as e:
 print(f'Primary failed: {e}. Running fallback.')
 return fallback_fn()

